// 📁 src/app/pages/search-results/search-results.component.ts

import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable, Subject, combineLatest } from 'rxjs';
import { takeUntil, map, startWith } from 'rxjs/operators';

// Importar desde la nueva arquitectura
import { Property } from '../../core/models/property.interface';
import { 
  SearchParams, 
  Filters, 
  SearchResultsConfig, 
  SORT_OPTIONS,
  PropertyTypeFilters,
  AmenityFilters,
  ExperienceFilters 
} from '../../core/models/search.interface';
import { PropertyService } from '../../core/services/property.service';
import { SearchService } from '../../core/services/search.service';

// 🔥 TEMPORAL: Importar FiltersPanel cuando esté disponible
// import { FiltersPanelComponent } from '../../shared/components/filters-panel/filters-panel.component';

@Component({
  selector: 'app-search-results',
  standalone: true,
  imports: [
    CommonModule, 
    FormsModule
    // 🔥 AGREGAR CUANDO ESTÉ DISPONIBLE: FiltersPanelComponent
  ],
  templateUrl: './search-results.component.html',
  styleUrl: './search-results.component.scss'
})
export class SearchResultsComponent implements OnInit, OnDestroy {

  // 🎯 OBSERVABLES REACTIVOS
  searchParams$: Observable<SearchParams>;
  filters$: Observable<Filters>;
  config$: Observable<SearchResultsConfig>;
  filteredProperties$: Observable<Property[]>;
  
  // 📊 ESTADO DEL COMPONENTE
  isLoading = true;
  searchError: string | null = null;
  totalResults = 0;
  
  // 🔍 Datos del formulario de búsqueda
  searchData: SearchParams = {
    destination: '',
    checkIn: '',
    checkOut: '',
    guests: 1
  };
  
  // 🔧 CONFIGURACIÓN
  readonly sortOptions = SORT_OPTIONS;
  readonly itemsPerPageOptions = [6, 12, 24];
  
  // 🧹 CLEANUP
  private destroy$ = new Subject<void>();

  // 🏛️ DESTINOS para el dropdown
  readonly destinations = [
    { value: '', label: 'Todos los destinos' },
    { value: 'salento', label: 'Salento' },
    { value: 'valle-cocora', label: 'Valle de Cocora' },
    { value: 'filandia', label: 'Filandia' },
    { value: 'armenia', label: 'Armenia' },
    { value: 'calarca', label: 'Calarcá' },
    { value: 'montenegro', label: 'Montenegro' }
  ];

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private propertyService: PropertyService,
    private searchService: SearchService
  ) {
    // Inicializar observables
    this.searchParams$ = this.searchService.searchParams$;
    this.filters$ = this.searchService.filters$;
    this.config$ = this.searchService.config$;
    this.filteredProperties$ = this.searchService.getFilteredResults();
  }

  ngOnInit(): void {
    this.initializeFromQueryParams();
    this.setupFilteredResults();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  /**
   * 🔗 Inicializar desde parámetros de URL
   */
  private initializeFromQueryParams(): void {
    this.route.queryParams
      .pipe(takeUntil(this.destroy$))
      .subscribe(params => {
        const searchParams: SearchParams = {
          destination: params['destination'] || '',
          checkIn: params['checkIn'] || '',
          checkOut: params['checkOut'] || '',
          guests: parseInt(params['guests']) || 1
        };

        // Sincronizar con formulario local
        this.searchData = { ...searchParams };

        // Actualizar parámetros en el servicio
        this.searchService.updateSearchParams(searchParams);
        
        console.log('🔍 Parámetros de búsqueda inicializados:', searchParams);
      });
  }

  /**
   * 🔄 Configurar suscripción a resultados filtrados
   */
  private setupFilteredResults(): void {
    this.filteredProperties$
      .pipe(
        takeUntil(this.destroy$),
        startWith([])
      )
      .subscribe({
        next: (properties) => {
          this.totalResults = properties.length;
          this.isLoading = false;
          console.log(`✅ ${properties.length} propiedades encontradas`);
        },
        error: (error) => {
          this.isLoading = false;
          this.searchError = 'Error al cargar las propiedades. Inténtalo de nuevo.';
          console.error('❌ Error en búsqueda:', error);
        }
      });
  }

  /**
   * 🔍 Realizar nueva búsqueda
   */
  performSearch(searchParams?: SearchParams): void {
    this.isLoading = true;
    this.searchError = null;
    
    // Usar parámetros proporcionados o los del formulario
    const params = searchParams || this.searchData;
    
    // Actualizar parámetros de búsqueda
    this.searchService.updateSearchParams(params);
    
    // Actualizar URL
    this.router.navigate([], {
      relativeTo: this.route,
      queryParams: params,
      queryParamsHandling: 'merge'
    });

    console.log('🔍 Nueva búsqueda realizada:', params);
  }

  /**
   * 🎛️ Actualizar filtros - TIPO CORREGIDO
   */
  updateFilters(filterUpdate: Partial<Filters>): void {
    this.searchService.updateFilters(filterUpdate);
    console.log('🎛️ Filtros actualizados:', filterUpdate);
  }

  /**
   * 🧹 Limpiar todos los filtros
   */
  clearFilters(): void {
    this.searchService.clearFilters();
    console.log('🧹 Filtros limpiados');
  }

  /**
   * 📊 Cambiar criterio de ordenamiento
   */
  updateSortBy(sortBy: string): void {
    this.searchService.setSortBy(sortBy);
    console.log('📊 Ordenamiento cambiado a:', sortBy);
  }

  /**
   * 👁️ Cambiar modo de vista
   */
  setViewMode(mode: 'list' | 'map'): void {
    this.searchService.setViewMode(mode);
    console.log('👁️ Modo de vista cambiado a:', mode);
  }

  /**
   * 📄 Cambiar página actual
   */
  goToPage(page: number): void {
    this.searchService.setCurrentPage(page);
    console.log('📄 Página cambiada a:', page);
    
    // Scroll al inicio de resultados
    const resultsElement = document.querySelector('.search-main');
    if (resultsElement) {
      resultsElement.scrollIntoView({ behavior: 'smooth' });
    }
  }

  /**
   * 📄 Cambiar items por página
   */
  updateItemsPerPage(itemsPerPage: number): void {
    this.searchService.updateConfig({ 
      itemsPerPage, 
      currentPage: 1 // Reset a primera página
    });
  }

  /**
   * 🏠 Ver detalles de propiedad
   */
  viewProperty(propertyId: string): void {
    // Registrar visualización
    this.propertyService.incrementPropertyViews(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe();

    // Navegar a detalles
    this.router.navigate(['/property', propertyId]);
    console.log('🏠 Navegando a propiedad:', propertyId);
  }

  /**
   * ⚡ Reserva rápida
   */
  quickBook(propertyId: string): void {
    // Combinar parámetros de búsqueda actuales
    combineLatest([this.searchParams$])
      .pipe(takeUntil(this.destroy$))
      .subscribe(([searchParams]) => {
        this.router.navigate(['/booking', propertyId], {
          queryParams: searchParams
        });
        console.log('⚡ Reserva rápida para:', propertyId);
      });
  }

  /**
   * ❤️ Toggle favorito
   */
  toggleFavorite(propertyId: string): void {
    this.propertyService.toggleFavorite(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (isFavorite) => {
          console.log(`${isFavorite ? '❤️' : '🤍'} Favorito actualizado:`, propertyId);
        },
        error: (error) => {
          console.error('❌ Error al actualizar favorito:', error);
        }
      });
  }

  /**
   * 🗺️ Seleccionar propiedad en mapa
   */
  selectProperty(propertyId: string): void {
    console.log('🗺️ Propiedad seleccionada en mapa:', propertyId);
    // Aquí implementarías lógica específica del mapa
  }

  /**
   * 📊 Obtener propiedades paginadas
   */
  getPaginatedProperties(): Observable<Property[]> {
    return combineLatest([
      this.filteredProperties$,
      this.config$
    ]).pipe(
      map(([properties, config]) => {
        const startIndex = (config.currentPage - 1) * config.itemsPerPage;
        const endIndex = startIndex + config.itemsPerPage;
        return properties.slice(startIndex, endIndex);
      })
    );
  }

  /**
   * 📄 Obtener números de página - NULL SAFETY AGREGADO
   */
  getPageNumbers(): Observable<number[]> {
    return combineLatest([
      this.filteredProperties$,
      this.config$
    ]).pipe(
      map(([properties, config]) => {
        if (!properties || properties.length === 0) {
          return []; // 🔒 Retornar array vacío si no hay propiedades
        }
        
        const totalPages = Math.ceil(properties.length / config.itemsPerPage);
        return Array.from({ length: totalPages }, (_, i) => i + 1);
      })
    );
  }

  /**
   * 🏷️ Obtener nombre amigable del destino
   */
  getDestinationName(destination: string): string {
    const dest = this.destinations.find(d => d.value === destination);
    return dest ? dest.label : destination;
  }

  /**
   * 📝 TrackBy function para optimización
   */
  trackByPropertyId(index: number, property: Property): string {
    return property.id;
  }

  /**
   * 🔍 Validar si hay filtros activos
   */
  hasActiveFilters(): Observable<boolean> {
    return this.searchService.getFilterState().pipe(
      map(state => state.hasActiveFilters)
    );
  }

  /**
   * 🎯 Tracking de interacciones
   */
  trackInteraction(action: string, data?: any): void {
    console.log(`📊 Search Interaction: ${action}`, data);
    // Implementar analytics aquí
  }

  /**
   * 🔥 MÉTODOS TEMPORALES PARA FILTROS (hasta crear FiltersPanel)
   */
  
  /**
   * Handler temporal para filtros de precios
   */
  onPriceFilterClick(priceRange: { priceMin: number; priceMax: number }): void {
    this.updateFilters(priceRange);
  }

  /**
   * Métodos auxiliares para filtros de tipos de propiedad
   */
  togglePropertyType(type: keyof PropertyTypeFilters, value: boolean): void {
    this.updateFilters({
      propertyTypes: {
        finca: false,
        cabana: false, 
        hacienda: false,
        glamping: false,
        [type]: value
      }
    });
  }

  /**
   * Métodos auxiliares para filtros de amenidades
   */
  toggleAmenity(amenity: keyof AmenityFilters, value: boolean): void {
    this.updateFilters({
      amenities: {
        wifi: false,
        parking: false,
        pool: false,
        kitchen: false,
        breakfast: false,
        [amenity]: value
      }
    });
  }

  /**
   * Métodos auxiliares para filtros de experiencias
   */
  toggleExperience(experience: keyof ExperienceFilters, value: boolean): void {
    this.updateFilters({
      experiences: {
        coffeTour: false,
        hiking: false,
        birdwatching: false,
        thermalSprings: false,
        [experience]: value
      }
    });
  }

  /**
   * Método temporal para obtener el estado de filtros activos sincrónicamente
   */
  hasActiveFiltersSync(): boolean {
    // Para usar en *ngIf cuando no tenemos el componente FiltersPanel
    return false; // Temporal - cambiar cuando tengas filtros reales
  }
}
